uniform shader image;
uniform float2 size;
uniform float time;
uniform float cyan;
uniform float magenta;
uniform float exposure;

half4 main(float2 coord){half4 c=image.eval(coord);half3 s=c.rgb/max(c.a,0.0001);half l=dot(s,half3(0.2126,0.7152,0.0722));half3 ir=half3(l*0.35, l*cyan, l*magenta);s=mix(s,ir,half(0.55));s*=half(exp2(exposure));return half4(clamp(s,half3(0),half3(1))*c.a,c.a);}
